input.prompt:
You are implementing Task 2.1: Game State Management

## Task Description

Create the complete game state system for Vibe Voyager — an interactive space game. All state persists in localStorage (no backend).

### Files to Create

**1. `lib/types.ts`** — All TypeScript interfaces for the game:

```typescript
export type StatName = 'vibe' | 'architecture' | 'protocol' | 'command'

export interface PlayerStats {
  vibe: number
  architecture: number
  protocol: number
  command: number
}

export type Rank = 'Cadet' | 'Navigator' | 'Commander' | 'Admiral'
export type ShipType = 'spark' | 'architect' | 'sentinel'

export interface CrewMember {
  id: string
  name: string
  role: string
  description: string
  recruitedAt: string
  portrait: string
}

export interface InventoryItem {
  id: string
  name: string
  realWorldTool: string
  description: string
  icon: string
  acquiredAt: string
}

export type MissionStatus = 'locked' | 'available' | 'in_progress' | 'completed'

export interface MissionProgress {
  missionId: string
  status: MissionStatus
  score?: number
  completedAt?: string
}

export type ChallengeType = 'prompt-duel' | 'architect' | 'connect' | 'debug' | 'command' | 'dialogue'

export interface Mission {
  id: string
  planetId: PlanetId
  title: string
  subtitle: string
  description: string
  challengeType: ChallengeType
  statRewards: Partial<PlayerStats>
  itemReward?: string
  crewReward?: string
  order: number
  content: MissionContent
}

export interface MissionContent {
  briefing: DialogueNode[]
  learning: LearningBlock[]
  challenge: ChallengeData
  debrief: DialogueNode[]
}

export interface DialogueNode {
  speaker: string
  text: string
  choices?: DialogueChoice[]
}

export interface DialogueChoice {
  text: string
  correct?: boolean
  response?: string
  nextNodeIndex?: number
}

export interface LearningBlock {
  type: 'text' | 'code' | 'stat' | 'image'
  content: string
  highlight?: boolean
}

export interface ChallengeData {
  type: ChallengeType
  instructions: string
  data: Record<string, unknown>
  passingScore: number
}

export type PlanetId = 'vibe-world' | 'debt-belt' | 'mcp-station' | 'agent-academy' | 'framework-nebula' | 'orchestration-citadel' | 'security-fortress' | 'production-worlds'
export type PlanetStatus = 'locked' | 'available' | 'in_progress' | 'completed'

export interface GameState {
  callsign: string
  ship: ShipType
  stats: PlayerStats
  crew: string[]
  inventory: string[]
  missionProgress: Record<string, MissionProgress>
  currentPlanet?: PlanetId
  currentMission?: string
  createdAt: string
  lastPlayedAt: string
}
```

**2. `lib/game-state.ts`** — State management functions:

```typescript
import { GameState, PlayerStats, Rank, PlanetId, PlanetStatus, ShipType, MissionProgress } from './types'

const SAVE_KEY = 'vibe-voyager-save'

const DEFAULT_STATS: PlayerStats = { vibe: 1, architecture: 1, protocol: 1, command: 1 }

// Planet prerequisites — which planets must be completed before each unlocks
const PLANET_PREREQUISITES: Record<PlanetId, PlanetId[]> = {
  'vibe-world': [],
  'debt-belt': ['vibe-world'],
  'mcp-station': ['debt-belt'],
  'agent-academy': ['mcp-station'],
  'framework-nebula': ['agent-academy'],
  'orchestration-citadel': ['framework-nebula'],
  'security-fortress': ['orchestration-citadel'],
  'production-worlds': ['security-fortress'],
}

export function createNewGame(callsign: string, ship: ShipType): GameState {
  const now = new Date().toISOString()
  return {
    callsign,
    ship,
    stats: { ...DEFAULT_STATS },
    crew: ['[REDACTED_PROJECT]'], // ARIA is always recruited at start
    inventory: [],
    missionProgress: {},
    createdAt: now,
    lastPlayedAt: now,
  }
}

export function saveGame(state: GameState): void {
  const updated = { ...state, lastPlayedAt: new Date().toISOString() }
  localStorage.setItem(SAVE_KEY, JSON.stringify(updated))
}

export function loadGame(): GameState | null {
  if (typeof window === 'undefined') return null
  const saved = localStorage.getItem(SAVE_KEY)
  if (!saved) return null
  try {
    return JSON.parse(saved) as GameState
  } catch {
    return null
  }
}

export function deleteGame(): void {
  localStorage.removeItem(SAVE_KEY)
}

export function hasSave(): boolean {
  if (typeof window === 'undefined') return false
  return localStorage.getItem(SAVE_KEY) !== null
}

export function getTotalStats(stats: PlayerStats): number {
  return stats.vibe + stats.architecture + stats.protocol + stats.command
}

export function getRank(stats: PlayerStats): Rank {
  const total = getTotalStats(stats)
  if (total >= 31) return 'Admiral'
  if (total >= 21) return 'Commander'
  if (total >= 11) return 'Navigator'
  return 'Cadet'
}

export function isPlanetComplete(planetId: PlanetId, state: GameState, missionCounts: Record<PlanetId, number>): boolean {
  const count = missionCounts[planetId] || 0
  let completed = 0
  for (const [id, progress] of Object.entries(state.missionProgress)) {
    if (id.startsWith(planetId) && progress.status === 'completed') completed++
  }
  return completed >= count
}

export function getPlanetStatus(planetId: PlanetId, state: GameState, missionCounts: Record<PlanetId, number>): PlanetStatus {
  // Check if planet is complete
  if (isPlanetComplete(planetId, state, missionCounts)) return 'completed'

  // Check if any missions started on this planet
  const hasProgress = Object.keys(state.missionProgress).some(
    id => id.startsWith(planetId) && state.missionProgress[id].status !== 'locked'
  )
  if (hasProgress) return 'in_progress'

  // Check prerequisites
  const prereqs = PLANET_PREREQUISITES[planetId]
  const allPrereqsMet = prereqs.every(p => isPlanetComplete(p, state, missionCounts))

  return allPrereqsMet ? 'available' : 'locked'
}

export function completeMission(state: GameState, missionId: string, score: number, statRewards: Partial<PlayerStats>, itemReward?: string, crewReward?: string): GameState {
  const newState = { ...state }

  // Update mission progress
  newState.missionProgress = {
    ...state.missionProgress,
    [missionId]: {
      missionId,
      status: 'completed',
      score,
      completedAt: new Date().toISOString(),
    },
  }

  // Add stat rewards
  newState.stats = addStatPoints(state.stats, statRewards)

  // Add item reward
  if (itemReward && !state.inventory.includes(itemReward)) {
    newState.inventory = [...state.inventory, itemReward]
  }

  // Recruit crew
  if (crewReward && !state.crew.includes(crewReward)) {
    newState.crew = [...state.crew, crewReward]
  }

  // Save immediately
  saveGame(newState)

  return newState
}

function addStatPoints(stats: PlayerStats, rewards: Partial<PlayerStats>): PlayerStats {
  return {
    vibe: Math.min(10, stats.vibe + (rewards.vibe || 0)),
    architecture: Math.min(10, stats.architecture + (rewards.architecture || 0)),
    protocol: Math.min(10, stats.protocol + (rewards.protocol || 0)),
    command: Math.min(10, stats.command + (rewards.command || 0)),
  }
}

export function getCompletedMissionCount(state: GameState): number {
  return Object.values(state.missionProgress).filter(p => p.status === 'completed').length
}

export function getMissionProgress(state: GameState, missionId: string): MissionProgress | undefined {
  return state.missionProgress[missionId]
}
```

**3. `lib/game-context.tsx`** — React context for game state:

```tsx
'use client'

import { createContext, useContext, useState, useCallback, useEffect, ReactNode } from 'react'
import { GameState, PlayerStats, ShipType } from './types'
import { createNewGame, saveGame, loadGame, deleteGame, completeMission as completeMissionFn, getRank, getTotalStats, getCompletedMissionCount } from './game-state'

interface GameContextType {
  state: GameState | null
  loading: boolean
  startNewGame: (callsign: string, ship: ShipType) => void
  resetGame: () => void
  completeMission: (missionId: string, score: number, statRewards: Partial<PlayerStats>, itemReward?: string, crewReward?: string) => void
  rank: string
  totalStats: number
  completedMissions: number
}

const GameContext = createContext<GameContextType | null>(null)

export function GameProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<GameState | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const saved = loadGame()
    setState(saved)
    setLoading(false)
  }, [])

  const startNewGame = useCallback((callsign: string, ship: ShipType) => {
    const newState = createNewGame(callsign, ship)
    saveGame(newState)
    setState(newState)
  }, [])

  const resetGame = useCallback(() => {
    deleteGame()
    setState(null)
  }, [])

  const completeMissionCb = useCallback((missionId: string, score: number, statRewards: Partial<PlayerStats>, itemReward?: string, crewReward?: string) => {
    setState(prev => {
      if (!prev) return prev
      return completeMissionFn(prev, missionId, score, statRewards, itemReward, crewReward)
    })
  }, [])

  const rank = state ? getRank(state.stats) : 'Cadet'
  const totalStats = state ? getTotalStats(state.stats) : 4
  const completedMissions = state ? getCompletedMissionCount(state) : 0

  return (
    <GameContext.Provider value={{
      state,
      loading,
      startNewGame,
      resetGame,
      completeMission: completeMissionCb,
      rank,
      totalStats,
      completedMissions,
    }}>
      {children}
    </GameContext.Provider>
  )
}

export function useGame() {
  const context = useContext(GameContext)
  if (!context) {
    throw new Error('useGame must be used within a GameProvider')
  }
  return context
}
