```tsx
'use client'

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react'
import { audio } from '@/lib/audio'

interface AudioContextType {
  muted: boolean
  toggleMute: () => void
  playSFX: (name: string) => void
}

const AudioContext = createContext<AudioContextType>({
  muted: false,
  toggleMute: () => {},
  playSFX: () => {},
})

export function AudioProvider({ children }: { children: ReactNode }) {
  const [muted, setMuted] = useState(false)
  const [userInteracted, setUserInteracted] = useState(false)

  useEffect(() => {
    audio.init()
    setMuted(audio.muted)

    // Start ambient audio on first user interaction (browser autoplay policy)
    const handleInteraction = () => {
      if (!userInteracted) {
        setUserInteracted(true)
        audio.playAmbient()
      }
    }

    window.addEventListener('click', handleInteraction, { once: true })
    window.addEventListener('keydown', handleInteraction, { once: true })

    return () => {
      window.removeEventListener('click', handleInteraction)
      window.removeEventListener('keydown', handleInteraction)
    }
  }, [userInteracted])

  const toggleMute = useCallback(() => {
    const newMuted = audio.toggleMute()
    setMuted(newMuted)
    if (newMuted) {
      audio.stopAmbient()
    } else {
      audio.playAmbient()
    }
  }, [])

  const playSFX = useCallback((name: string) => {
    audio.playSFX(name as any)
  }, [])

  return (
    <AudioContext.Provider value={{ muted, toggleMute, playSFX }}>
      {children}
    </AudioContext.Provider>
  )
}

export function useAudio() {
  return useContext(AudioContext)
}

export function AudioToggle() {
